def fig_cooling():
    """冷却曲線（模式図）。凝固後の直線を延長して、冷却直線との交点（ウ）を作図する"""
    W, H, ox, oy = 340, 215, 40, 195
    P0, Pmin, Ppk, Pend = (45, 28), (165, 170), (180, 118), (320, 140)
    m1 = (Pmin[1] - P0[1]) / (Pmin[0] - P0[0])
    m2 = (Pend[1] - Ppk[1]) / (Pend[0] - Ppk[0])
    # 交点：P0 + m1 (x-x0) = Ppk + m2 (x-xpk)
    xi = (Ppk[1] - P0[1] + m1 * P0[0] - m2 * Ppk[0]) / (m1 - m2)
    yi = P0[1] + m1 * (xi - P0[0])
    xe = 270; ye = Ppk[1] + m2 * (xe - Ppk[0])
    yf = 86   # 純溶媒の凝固点（ウより高温＝上）
    o = [f'<svg class="fig" width="{W}" height="{H}" viewBox="0 0 {W} {H}" xmlns="http://www.w3.org/2000/svg" font-size="10">',
         f'<line x1="{ox}" y1="{oy}" x2="{W-8}" y2="{oy}" stroke="#000"/><line x1="{ox}" y1="{oy}" x2="{ox}" y2="8" stroke="#000"/>',
         f'<text x="{W-8}" y="{oy+13}" text-anchor="end">時間</text>',
         f'<text x="{ox-5}" y="16" text-anchor="end">温度</text>',
         f'<polyline fill="none" stroke="#000" stroke-width="1.6" points="{P0[0]},{P0[1]} {Pmin[0]},{Pmin[1]} {Ppk[0]},{Ppk[1]} {Pend[0]},{Pend[1]}"/>',
         f'<line x1="{xi:.1f}" y1="{yi:.1f}" x2="{Ppk[0]}" y2="{Ppk[1]}" stroke="#000" stroke-dasharray="4,3"/>',
         f'<line x1="{ox}" y1="{yf}" x2="{W-10}" y2="{yf}" stroke="#888" stroke-dasharray="2,3"/>',
         f'<text x="{W-10}" y="{yf-4}" text-anchor="end" font-size="9">純粋なベンゼンの凝固点</text>']
    for (x, y), lab, dx, dy in [(Pmin, "ア", 2, 14), (Ppk, "イ", 0, -7), ((xi, yi), "ウ", -17, 13), ((xe, ye), "エ", -2, -7)]:
        o.append(f'<circle cx="{x:.1f}" cy="{y:.1f}" r="2.8"/><text x="{x+dx:.1f}" y="{y+dy:.1f}" font-size="11">{lab}</text>')
    o.append("</svg>")
    return "".join(o), (xi, yi), yf, Ppk


FIG_COOL, _XI, _YF, _PPK = fig_cooling()

