def _parse(s):
    st, i = [Counter()], 0
    while i < len(s):
        if s[i] in "([":
            st.append(Counter()); i += 1
        elif s[i] in ")]":
            m = re.match(r"\d*", s[i + 1:]); k = int(m.group() or 1); i += 1 + len(m.group())
            top = st.pop()
            for e, c in top.items():
                st[-1][e] += k * c
        else:
            m = re.match(r"([A-Z][a-z]?)(\d*)", s[i:])
            st[-1][m.group(1)] += int(m.group(2) or 1); i += len(m.group())
    return st[0]


def verify():
    items = CH[6]["items"]
    lv = [it["lv"] for it in items]
    assert lv == sorted(lv) and lv.count("A") == 4 and 4 <= lv.count("B") <= 5 and lv.count("C") == 2
    for it in items:
        for k in ("tag", "q", "a", "s"):
            assert it[k].strip(), k
        for k in ("q", "a", "s"):
            assert it[k].count("$") % 2 == 0 and "$$" not in it[k], it[k][:30]
        assert "<b>ポイント</b>" in it["s"]

    def sig(x, n=2):
        return round(x, n - 1 - int(floor(log10(abs(x)))))

    def eq(x, v, n=2):
        assert abs(sig(x, n) - v) <= 1e-9 * abs(v), (x, sig(x, n), v)

    # A2 溶解度
    eq(109 / 209 * 100, 52.2, 3); eq(109 - 31.6, 77.4, 3); eq(100 * 77.4 / 209, 37.0, 3); eq(20 * 109 / 100, 21.8, 3)
    # A3 ヘンリー
    n = 1.4e-3 * 5.0; eq(n, 7.0e-3); eq(n * 32, 0.22); eq(n * R * 293 / 5.0e5 * 1000, 34)
    eq(1.4e-3 * R * 293 / 1.0e5 * 1000, 34); eq(1.4e-3 * 0.20, 2.8e-4)
    # A4 束一的性質
    eq(1.85 * 18 / 180 / 0.500, 0.37); assert round(100 + 0.52 * 0.20, 2) == 100.10
    conc = {"ア": 0.10, "イ": 0.20, "ウ": 0.30, "エ": 0.15}
    assert sorted(conc, key=lambda k: -conc[k]) == ["ウ", "イ", "エ", "ア"]
    # B1 冷却曲線・分子量
    xi, yi = _XI
    assert _YF < yi < _PPK[1]          # 純溶媒の凝固点 > ウ > イ（図の上ほど高温）
    m = 0.128 / 5.12; eq(m, 0.0250, 3); M = 0.640 / (m * 0.100); eq(M, 256, 3); assert round(M / 32) == 8
    # B2 浸透圧
    eq(0.90 / 180 / 0.100 * R * 300, 1.2e5); eq(0.50 * R * 300 / (2.5e2 * 0.100), 5.0e4)
    eq(2.5e2 / (1.0e3 * 9.8) * 100, 2.6); eq(1.85 * (0.50 / 5.0e4) / 0.100, 1.9e-4)
    # B3 電離度
    eq(0.333 / (1.85 * 0.10) - 1, 0.80)
    # B4 密閉容器
    kg, ks = 4.15 / (R * 300), 3.3e-2 / 1.0e5
    P = 0.12 / (kg + ks); eq(P, 6.0e4); eq(ks * P, 2.0e-2); eq(kg, 1.67e-6, 3); eq(kg + ks, 2.0e-6)
    # B5 反応式
    l, r = Counter(), Counter()
    for k, f in [(1, "FeCl3"), (3, "H2O")]:
        for e, c in _parse(f).items(): l[e] += k * c
    for k, f in [(1, "Fe(OH)3"), (3, "HCl")]:
        for e, c in _parse(f).items(): r[e] += k * c
    assert l == r
    # C1 会合
    mm = 0.563 / 5.12; eq(mm, 0.110, 3); npart = mm * 0.0500
    eq(0.60 / npart, 1.1e2); beta = 2 * (1 - npart / (0.60 / 60)); eq(beta * 100, 90)
    # C2 U 字管
    Pi = 98 * 10.0; eq(Pi, 9.8e2); V = 100 + 10.0 / 2 * 2.0; assert V == 110
    M = 1.0 * R * 300 / (Pi * V / 1000); eq(M, 2.3e4); eq(1.0 * R * 300 / (Pi * 0.100), 2.5e4)
    eq(1.0 / M * R * 300 / 0.100, 1.1e3); eq(1.0 / 2.3e4 * R * 300 / 0.100, 1.1e3)
